// ----- Admin -----
/** Purposes the server will mail a confirmation code for. */
export type OtpPurpose = "password" | "passkey" | "purge";

export const accountApi = {
  /** Mails a code to the account's own address. The address is never sent by
   *  the client — the server reads it off the session. */
  requestOtp: (purpose: OtpPurpose) =>
    jfetch<{ sent: true; email: string; purpose: OtpPurpose; ttl_secs: number; resend_in: number }>(
      "/api/account/otp",
      { method: "POST", body: JSON.stringify({ purpose }) },
    ),
  uploadAvatar: (file: File) => {
    const form = new FormData();
    form.append("file", file);
    return jfetch<{ ok: true; avatar_url: string }>("/api/account/avatar", { method: "POST", body: form });
  },
  removeAvatar: () => jfetch<{ ok: true }>("/api/account/avatar", { method: "DELETE" }),
  setNickname: (name: string) =>
    jfetch<{ ok: true; name: string }>("/api/account/profile", {
      method: "PATCH",
      body: JSON.stringify({ name }),
    }),
  changePassword: (newPassword: string, code: string) =>
    jfetch<{ ok: true }>("/api/account/password", {
      method: "POST",
      body: JSON.stringify({ new_password: newPassword, code }),
    }),
};

