/** Gallery sort orders. Mirrors the whitelist in the backend's image handler —
 * an unknown value there falls back to newest rather than erroring. */
export const SORTS = [
  { key: "newest", label: "最新上传", icon: "fa-arrow-down-wide-short" },
  { key: "oldest", label: "最早上传", icon: "fa-arrow-up-wide-short" },
  { key: "largest", label: "占用最大", icon: "fa-weight-hanging" },
  { key: "smallest", label: "占用最小", icon: "fa-feather" },
  { key: "widest", label: "分辨率最高", icon: "fa-expand" },
  { key: "name", label: "文件名", icon: "fa-arrow-down-a-z" },
] as const;

export type SortKey = (typeof SORTS)[number]["key"];

/** Formats a byte count for display. Used everywhere space is shown. */
export function formatBytes(n: number, digits = 1): string {
  if (!n || n < 0) return "0 B";
  if (n < 1024) return `${n} B`;
  const units = ["KB", "MB", "GB", "TB", "PB"];
  let v = n / 1024;
  let i = 0;
  while (v >= 1024 && i < units.length - 1) {
    v /= 1024;
    i++;
  }
  return `${v.toFixed(digits)} ${units[i]}`;
}
